function check(bool $condition, string $label): void { global $checks; if (!$condition) throw new RuntimeException('FAIL: ' . $label); $checks++; echo "OK $label\n"; }
function rejects(callable $fn, string $label): void { try { $fn(); } catch (DomainException) { check(true, $label); return; } check(false, $label); }
function freshRequest(?string $document = null): array {
    global $db, $app;
    $number = $document ?? (string) random_int(2000000000, 2999999999);
    if (!$db->one('SELECT id FROM patients WHERE document_number=?', [$number])) $db->insert('patients', ['document_type'=>'CC','document_number'=>$number,'full_name'=>'Paciente de prueba','email'=>$app->config['test_recipient'],'email_verified_at'=>$app->now()]);
