    $job = $db->one("SELECT * FROM jobs WHERE request_id=? AND kind='otp'", [$id]);
    return [$id, App\Crypto::open($job['encrypted_payload'], $app->config['app_key'])];
}
function verifiedRequest(): int { global $app; [$id,$code]=freshRequest(); check($app->verify($id,$code,'verify-'. $id), 'Código válido autoriza solicitud ' . $id); return $id; }
function addEncounter(int $patientId, int $days = 0, int $specialtyId = 1): array {
    global $db,$app;
    $encounterId=$db->insert('encounters',['patient_id'=>$patientId,'specialty_id'=>$specialtyId,'attended_at'=>date('Y-m-d 08:00:00',strtotime("$days days")),'admission'=>bin2hex(random_bytes(6)),'location'=>'Sede de prueba']);
    $packageId=$db->insert('packages',['encounter_id'=>$encounterId,'version'=>1,'status'=>'available','published_at'=>$app->now()]);
    $paths=[];
    foreach ([1,2] as $index) {
        $name=bin2hex(random_bytes(16)).'.pdf'; $path=$app->config['storage_path'].'/histories/'.$name;
        file_put_contents($path,"%PDF-1.4\nPDF ficticio de prueba $index\n%%EOF");
        $db->insert('clinical_files',['package_id'=>$packageId,'storage_name'=>$name,'original_name'=>'test.pdf','sort_order'=>$index,'size_bytes'=>filesize($path),'sha256'=>hash_file('sha256',$path)]);
        $paths[]=$path;
    }
    return [$encounterId,$packageId,$paths];
}
